  if (row.unsubscribed || row.bounced) return null;
  if (row.sinceLastHours !== null && row.sinceLastHours < MIN_SPACING_HOURS) return null;
  if (row.ageHours >= 7 * DAY2 && row.plan !== "cloud") return "day7";
  if (row.ageHours >= 5 * DAY2 && !row.hasMarketingRoom) return "marketing";
  if (row.ageHours >= 3 * DAY2 && row.lesson) return "day3";
