    if (brand.description) lines.push(`Description: ${brand.description}`);
    if (brand.palette.length) lines.push(`Palette: ${brand.palette.slice(0, 6).join(" ")}`);
    if (brand.fonts.length) lines.push(`Fonts: ${brand.fonts.slice(0, 3).join(", ")}`);
