function announceRoutes(app, store2, opts = {}) {
  const fetchFn = opts.fetchFn ?? fetch;
  const ann = () => store2.announcements;
  app.use("/announce/*", cors({ origin: siteOrigin, allowMethods: ["GET", "POST", "OPTIONS"] }));
  app.use("/announce", cors({ origin: siteOrigin, allowMethods: ["POST", "OPTIONS"] }));
  const installationFor2 = (slug) => installationFor(ann(), slug, fetchFn);
  app.post("/announce/detect", async (c) => {
    if (!ann()) return c.json({ ok: false, reason: "unconfigured" }, 501);
    const body = DetectSchema.safeParse(await c.req.json().catch(() => null));
    const parsed = body.success ? parseRepoInput(body.data.repo) : null;
    if (!parsed) return c.json({ ok: false, reason: "invalid" });
    const slug = parsed.slug;
    let token = null;
    let repo = await githubGet(`/repos/${slug}`, { fetchFn });
    let installed = false;
    if (repo.status !== 200) {
      const inst = await installationFor2(slug);
      if (inst) {
        token = (await installationToken(inst.installationId, { fetchFn }).catch(() => null))?.token ?? null;
        if (token) {
          repo = await githubGet(`/repos/${slug}`, { token, fetchFn });
          installed = repo.status === 200;
        }
      }
      if (repo.status !== 200) return c.json({ ok: true, slug, private: true, installed: false, latest: null, prs: 0, homepage: null, install: githubAppConfigured() ? installUrl(slug) : null });
    }
    const facts = repo.json;
    const { latest, prs } = await latestOf(slug, token, fetchFn);
    return c.json({ ok: true, slug, private: !!facts.private, installed: installed || !facts.private, latest, prs, homepage: facts.homepage ?? null, install: null });
  });
  app.post("/announce", async (c) => {
    if (!ann()) return c.json({ error: "The door is not open on this server." }, 501);
    const body = CreateSchema.safeParse(await c.req.json().catch(() => null));
    if (!body.success) return c.json({ error: "Give the repository, your website and your email." }, 422);
    const parsed = parseRepoInput(body.data.repo);
    if (!parsed) return c.json({ error: "That is not a GitHub repository address." }, 422);
    const email = body.data.email.toLowerCase();
    if (!EMAIL_RE.test(email)) return c.json({ error: "That email address does not look right." }, 422);
    const website = body.data.website.replace(/^https?:\/\//, "").replace(/\/+$/, "");
    if (!/^[\w.-]+\.[a-z]{2,}(\/.*)?$/i.test(website)) return c.json({ error: "That website address does not look right." }, 422);
    const ipHash = ipHashOf(c.req.header("x-forwarded-for")?.split(",")[0] ?? c.req.header("x-real-ip"));
    const now = Date.now();
    const day3 = new Date(now - 864e5).toISOString();
    const hour = new Date(now - 36e5).toISOString();
    if (await ann().countSince({ email, sinceIso: day3 }) >= cap("ANNOUNCE_EMAIL_CAP", 5)) return c.json({ error: "This email already asked for five draft sets today. Try again tomorrow." }, 429);
    if (ipHash && await ann().countSince({ ipHash, sinceIso: hour }) >= cap("ANNOUNCE_IP_CAP", 10)) return c.json({ error: "Too many requests from this address. Try again in an hour." }, 429);
    if (await ann().countSince({ sinceIso: day3 }) >= cap("ANNOUNCE_DAILY_CAP", 200)) return c.json({ error: "The door is busy today. Try again tomorrow." }, 429);
    const inst = await installationFor2(parsed.slug);
    let tag = body.data.tag ?? null;
    if (!tag) {
      const token = inst ? (await installationToken(inst.installationId, { fetchFn }).catch(() => null))?.token ?? null : null;
      tag = (await latestOf(parsed.slug, token, fetchFn).catch(() => ({ latest: null }))).latest?.tag ?? null;
    }
    const made = await ann().create({ repo: parsed.slug, tag, website, email, private: !!inst, installationId: inst?.installationId ?? null, ipHash });
    if (made) return c.json({ id: made.id, status: "queued" }, 202);
    const existing = tag ? await ann().find({ repo: parsed.slug, tag, email }) : null;
    if (existing) return c.json({ id: existing.id, status: existing.status }, 200);
    return c.json({ error: "That request could not be saved. Try again." }, 500);
  });
  app.get("/announce/:id", async (c) => {
    const row = ann() ? await ann().get(c.req.param("id")) : null;
    if (!row) return c.json({ error: "not found" }, 404);
    const { releaseBriefFrom: releaseBriefFrom2, whyBelowTitle: whyBelowTitle2 } = await Promise.resolve().then(() => (init_src(), src_exports));
    const b2 = row.brief ? releaseBriefFrom2("release-report.md", row.brief) : null;
    return c.json(announceView(row, b2 ? { title: b2.title, verdict: b2.verdict, why: whyBelowTitle2(b2) } : null));
  });
  app.get("/announce/:id/image", async (c) => {
    const img = ann() ? await ann().image(c.req.param("id")) : null;
    if (!img) return c.text("not found", 404);
    return new Response(Buffer.from(img.bytes), { headers: { "content-type": img.mime, "cache-control": "public, max-age=86400" } });
  });
  githubConnectRoutes(app, store2, { fetchFn });
  app.get("/internal/announce-due", async (c) => {
    const secret = process.env["CRON_SECRET"];
    if (!secret || c.req.header("authorization") !== `Bearer ${secret}`) return c.json({ error: "forbidden" }, 403);
    if (!ann()) return c.json({ processed: 0, note: "announcements not served by this store" });
    const mail = (row, email) => queueAndSend(store2, { toEmail: row.email, template: "announce-ready", kind: "transactional", dedupeKey: `announce:${row.id}`, payload: { id: row.id, repo: row.repo, tag: row.tag } }, email, null);
    const deps = { ...defaultDeps(mail), ...opts.deps };
    const rows2 = await ann().claimQueued(1);
    const results = [];
    for (const row of rows2) results.push({ id: row.id, ...await runAnnounceJob(ann(), row, deps) });
    return c.json({ processed: rows2.length, results });
  });
}
function announceClaimRoute(app, store2, opts = {}) {
  githubApiRoutes(app, store2, { fetchFn: opts.fetchFn });
  app.post("/v1/announce/:id/claim", async (c) => {
    const ann = store2.announcements;
    if (!ann) return c.json({ error: "announcements not served by this store" }, 501);
    const actor = c.get("actor");
    if (actor.kind !== "human") return c.json({ error: "a person claims a draft set", code: "HUMAN_ONLY" }, 403);
    const body = z15.object({ workspace: z15.string().min(1) }).safeParse(await c.req.json().catch(() => null));
    if (!body.success) return c.json({ error: "invalid body" }, 400);
    if (!await actorInWorkspace(store2, actor, body.data.workspace)) return c.json({ error: "not your workspace", code: "NOT_PERMITTED" }, 403);
    const row = await ann.get(c.req.param("id"));
    if (!row) return c.json({ error: "not found" }, 404);
    if (row.status !== "ready") return c.json({ error: "The drafts are not ready yet." }, 409);
    if (row.claimedThreadId) return c.json({ threadId: row.claimedThreadId, workspace: row.claimedWorkspaceId, already: true });
    const out = await claimAnnouncement(store2, ann, actor, body.data.workspace, row);
    return c.json({ ...out, workspace: body.data.workspace });
  });
}

// src/relay.ts
import { timingSafeEqual as timingSafeEqual4 } from "node:crypto";
import { z as z16 } from "zod";
var ValidateMachineSchema = z16.object({ token: z16.string().min(1) });
var ValidateClientSchema = z16.object({ clerkToken: z16.string().min(1), machineId: z16.string().uuid() });
var DevRelayUserSchema = z16.string().uuid();
function devRelayUser(token) {
  if (process.env["NM_ALLOW_DEV_RELAY"] !== "1") return null;
  const expected = process.env["NM_DEV_RELAY_TOKEN"];
  const parsed = DevRelayUserSchema.safeParse(process.env["NM_DEV_RELAY_USER"]);
  if (!expected || expected.length < 32 || !parsed.success) return null;
  const actualBytes = Buffer.from(token);
  const expectedBytes = Buffer.from(expected);
  if (actualBytes.length !== expectedBytes.length || !timingSafeEqual4(actualBytes, expectedBytes)) return null;
  return parsed.data;
}
function relayRoutes(app, store2, deps = {}) {
  if (process.env["NODE_ENV"] === "production" && process.env["NM_ALLOW_DEV_RELAY"] === "1") {
    throw new Error("NM_ALLOW_DEV_RELAY cannot be enabled in production");
  }
  const verifyClerk = deps.verifyClerk ?? verifyClerkToken;
  const relaySecretOk = (auth) => {
    const secret = process.env["RELAY_SECRET"];
    return Boolean(secret) && auth === `Bearer ${secret}`;
  };
  app.post("/internal/relay/validate-machine", async (c) => {
    if (!relaySecretOk(c.req.header("authorization"))) return c.json({ error: "forbidden" }, 403);
    if (!store2.machineByTokenHash) return c.json({ error: "fleet not served by this store" }, 501);
    const body = ValidateMachineSchema.safeParse(await c.req.json().catch(() => null));
    if (!body.success) return c.json({ error: "invalid body", issues: body.error.issues }, 400);
    if (!body.data.token.startsWith("nmm_")) return c.json({ error: "unknown machine token" }, 401);
    const row = await store2.machineByTokenHash(hashMachineToken(body.data.token));
    if (!row) return c.json({ error: "unknown machine token" }, 401);
    return c.json({ machineId: row.id, workspaceId: row.workspace_id });
  });
  app.post("/internal/relay/validate-client", async (c) => {
    if (!relaySecretOk(c.req.header("authorization"))) return c.json({ error: "forbidden" }, 403);
    if (!store2.machineWorkspace) return c.json({ error: "fleet not served by this store" }, 501);
    const body = ValidateClientSchema.safeParse(await c.req.json().catch(() => null));
    if (!body.success) return c.json({ error: "invalid body", issues: body.error.issues }, 400);
    let userId = devRelayUser(body.data.clerkToken);
    if (!userId) {
      let clerkId;
      try {
        clerkId = String((await verifyClerk(body.data.clerkToken)).sub);
      } catch {
        return c.json({ allowed: false });
      }
      userId = await store2.userIdForClerkId(clerkId);
      if (!userId) return c.json({ allowed: false });
    }
    const machine = await store2.machineWorkspace(body.data.machineId);
    if (!machine) return c.json({ allowed: false });
    const member = (await store2.listWorkspaces(userId)).some((w) => w.id === machine.workspaceId);
    if (!member) return c.json({ allowed: false });
    if (machine.kind === "member" && machine.ownerUserId !== userId) return c.json({ allowed: false });
    return c.json({ allowed: true, userId });
  });
}
async function machineWorkspace(sql, machineId) {
  const [row] = await sql`
    select workspace_id, kind, owner_user_id from machines
     where id = ${machineId}::uuid and kind <> 'local' and (lifecycle is null or lifecycle <> 'destroyed')
     limit 1`;
  return row ? { workspaceId: row.workspace_id, kind: row.kind, ownerUserId: row.owner_user_id } : null;
}

// src/bearer-auth.ts
async function resolveBearerActor(store2, userId, rawHeader) {
  let claim = null;
  try {
    const parsed = ActorSchema.safeParse(JSON.parse(rawHeader ?? "null"));
    claim = parsed.success ? parsed.data : null;
  } catch {
    claim = null;
  }
  if (!claim || claim.kind !== "agent") return { kind: "human", id: userId };
  const workspace = await store2.agentWorkspace(claim.id).catch(() => null);
  if (!workspace) return null;
  return (await store2.humanMemberIds(workspace)).includes(userId) ? claim : null;
}

