    const actor = c.get("actor");
    if (actor.kind !== "human") return c.json({ error: "the usage meter is human-only", code: "NOT_PERMITTED" }, 403);
    if (!(await store2.humanMemberIds(workspace)).includes(actor.id)) {
      return c.json({ error: "not a member of this workspace", code: "NOT_PERMITTED" }, 403);
    }
    if (!store2.machineUsageToday) return c.json({ error: "fleet not served by this store" }, 501);
    const usage = await store2.machineUsageToday(workspace);
    const plan = await store2.workspacePlan(workspace);
    const capMinutes = null;
    const sql = sqlOf(store2);
