function expoFetchSender(accessToken) {
  return {
    async send(messages) {
      const out = [];
      for (let i = 0; i < messages.length; i += 100) {
        const chunk2 = messages.slice(i, i + 100);
        try {
          const res = await fetch("https://exp.host/--/api/v2/push/send", {
            method: "POST",
            headers: {
              "content-type": "application/json",
              accept: "application/json",
              ...accessToken ? { authorization: `Bearer ${accessToken}` } : {}
            },
            body: JSON.stringify(chunk2),
            signal: AbortSignal.timeout(1e4)
          });
          const body = await res.json().catch(() => ({}));
          out.push(...body.data ?? chunk2.map(() => ({ status: "error", message: `expo push failed (${res.status})` })));
        } catch {
          out.push(...chunk2.map(() => ({ status: "error", message: "expo push request failed" })));
        }
      }
      return out;
    }
  };
}

