async function resolveChannelId(sql, workspace, ref, projectId) {
  if (UUID_RE.test(ref)) {
    const [c] = await sql`select id from channels where id = ${ref}::uuid and workspace_id = ${workspace}::uuid`;
    if (c) return c["id"];
    throw new DomainError("NOT_FOUND", `channel ${ref} not found`);
  }
  const rows2 = projectId ? await sql`select id from channels where workspace_id = ${workspace}::uuid and project_id = ${projectId}::uuid and slug = ${ref}` : await sql`select c.id from channels c join projects p on p.id = c.project_id
        where c.workspace_id = ${workspace}::uuid and c.slug = ${ref} order by p.is_default desc limit 1`;
  if (!rows2.length) throw new DomainError("NOT_FOUND", `channel ${ref} not found`);
  return rows2[0]["id"];
}
